import { useSyncExternalStore } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/useSession';
import { claimsKey } from '../claims/useClaims';

// The claims selected for a bulk action. Kept in a small store rather than the URL so a checkbox
// shows its new state on the same click (a URL update lands a render later). It belongs to one sheet:
// loading another starts with nothing selected.
const NONE: ReadonlySet<number> = new Set();
let selected: { sheetId: string; ids: ReadonlySet<number> } = { sheetId: '', ids: NONE };
const listeners = new Set<() => void>();
const selection = {
  subscribe: (l: () => void) => {
    listeners.add(l);
    return () => {
      listeners.delete(l);
    };
  },
  get: () => selected,
  set: (sheetId: string, ids: ReadonlySet<number>) => {
    selected = { sheetId, ids };
    listeners.forEach((l) => l());
  },
};
function useSelected(sheetId: string): ReadonlySet<number> {
  const current = useSyncExternalStore(selection.subscribe, selection.get);
  return current.sheetId === sheetId ? current.ids : NONE;
}

// A claim's checkbox selecting it for a bulk action.
function ClaimSelect({ sheetId, claim }: { sheetId: string; user: string; personId: number; claim: { id: number } }) {
  const chosen = useSelected(sheetId);
  return (
    <input
      type="checkbox"
      data-testid="claim-select"
      checked={chosen.has(claim.id)}
      onChange={(e) => {
        const next = new Set(chosen);
        if (e.target.checked) next.add(claim.id);
        else next.delete(claim.id);
        selection.set(sheetId, next);
      }}
    />
  );
}

type BulkOpenResult = { opened: number; refused: number };

// Opens the selected claims together; the server numbers them in list order and leaves any it cannot open
// as they are. Shows how many were opened and how many refused; the counts are gone while it runs.
function BulkOpen({ sheetId }: { sheetId: string; user: string }) {
  const chosen = useSelected(sheetId);
  const [user] = useUser();
  const queryClient = useQueryClient();
  const open = useMutation({
    mutationFn: (ids: number[]) => {
      if (ids.length === 0) throw new Error('Select the claims to open');
      return postJson<BulkOpenResult>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/bulk-open`, { ids, by: user ?? '' });
    },
    onSuccess: async () => {
      selection.set(sheetId, NONE);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  return (
    <section data-testid="bulk-actions">
      <button type="button" data-testid="bulk-open" disabled={open.isPending} onClick={() => open.mutate([...chosen])}>
        Open selected
      </button>{' '}
      {open.isSuccess && (
        <span>
          Opened <strong data-testid="bulk-opened">{open.data.opened}</strong>, refused{' '}
          <strong data-testid="bulk-refused">{open.data.refused}</strong>
        </span>
      )}
      {open.isError && (
        <span data-testid="bulk-open-error" role="alert">
          {open.error.message}
        </span>
      )}
    </section>
  );
}

type BulkSettleResult = { settled: number; refused: number };

// Settles the selected claims together; the server settles them in list order exactly as settling each alone
// (a clerk's settle above the limit leaves one PENDING, counted as settled) and leaves any it cannot settle as they
// are. Shows how many were settled and how many refused; the counts are gone while it runs.
function BulkSettle({ sheetId }: { sheetId: string; user: string }) {
  const chosen = useSelected(sheetId);
  const [user] = useUser();
  const queryClient = useQueryClient();
  const settle = useMutation({
    mutationFn: (ids: number[]) => {
      if (ids.length === 0) throw new Error('Select the claims to settle');
      return postJson<BulkSettleResult>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/bulk-settle`, { ids, by: user ?? '' });
    },
    onSuccess: async () => {
      selection.set(sheetId, NONE);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  return (
    <section data-testid="bulk-settle-actions">
      <button type="button" data-testid="bulk-settle" disabled={settle.isPending} onClick={() => settle.mutate([...chosen])}>
        Settle selected
      </button>{' '}
      {settle.isSuccess && (
        <span>
          Settled <strong data-testid="bulk-settled">{settle.data.settled}</strong>, refused{' '}
          <strong data-testid="bulk-settle-refused">{settle.data.refused}</strong>
        </span>
      )}
      {settle.isError && (
        <span data-testid="bulk-settle-error" role="alert">
          {settle.error.message}
        </span>
      )}
    </section>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 0, Component: ClaimSelect }),
  SheetBody.fill({ order: 15, Component: BulkOpen }),
  SheetBody.fill({ order: 16, Component: BulkSettle }),
];
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';

/**
 * The body of the screen once a user is signed in and a sheet is loaded. Every per-sheet feature
 * fills it; its context is the active sheet id and the signed-in user.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import type { Holds } from '../people/people.slot';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when the claim is opened: the sheet's next (1, 2, ...), or within its period (<period>-<n>, X-<n> in none); none for a draft. */
  number: string | null;
  /** The due fixed when the claim was settled; none while live (not settled, or settled without a rate). */
  settledDue: string | null;
  /** The signed-in user who opened the claim; none when it was never opened. They cannot settle it. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim: it then shows and totals `statedDue` (none: n/a). */
  stated: boolean;
  statedDue: string | null;
  /** The number of the SETTLED claim this correction (a negative amount) corrects; none for any other claim. */
  corrects: string | null;
  /** The date the claim is due by: fixed when it was added (its date plus its grade's terms then), never moved. */
  dueBy: string;
  /** The claim's status log, oldest first: `<STATUS> by <user> on <date> due=<due>`. */
  log: string[] };

/** Whether a claim counts toward claimed, due and every total: only OPEN, PENDING and SETTLED claims do, and an OPEN
 *  or PENDING one dated within one of its person's holds (`held`: each person's holds) does not unless a statement binds it. */
export function counts(claim: { status: ClaimStatus; personId: number; date: string; stated: boolean }, held: Holds): boolean {
  if (claim.status === 'OPEN' || claim.status === 'PENDING') {
    return claim.stated || !(held.get(claim.personId) ?? []).some((h) =>
      (h.from === null || h.from <= claim.date) && (h.to === null || claim.date <= h.to));
  }
  return claim.status === 'SETTLED';
}

/** The key every feature reads the sheet's claims under. */
export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** Which claim's editor is open (search param `editClaim`); none means each claim form adds. */
export function useEditingClaim() {
  return useSearchParam('editClaim', asNumber);
}

/** The counted claims' amounts added up exactly, in cents, shown with two decimals. */
export function sumAmounts(claims: Claim[], held: Holds): string {
  const cents = claims.filter((c) => counts(c, held)).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
import { useRef } from 'react';
